package cmd

import (
	"fmt"
	"strings"
	"testing"
)

const gatewayMasterKeyLine = "master_key: os.environ/LITELLM_MASTER_KEY"

// The register entries for GHSA-7hp6-4w63-5g45 and GHSA-g5ff-637f-6q2m rest on one fact: the
// gateway has no user or key store, so no non-admin principal can exist. Both gateway configs are
// generated by quickstart.sh, so that file is where a database would first appear.
func gatewayConfigNoDBViolations(quickstart string) []string {
	const consequence = "the .github/advisory-exceptions.json entries for GHSA-7hp6-4w63-5g45 and GHSA-g5ff-637f-6q2m " +
		"assume the LiteLLM gateway has no user/key database; re-evaluate them before the gateway config gains one"
	var out []string
	if n := strings.Count(strings.ToLower(quickstart), "database_url"); n != 0 {
		out = append(out, fmt.Sprintf("quickstart.sh mentions database_url %d time(s): %s", n, consequence))
	}
	if n := strings.Count(quickstart, gatewayMasterKeyLine); n != 2 {
		out = append(out, fmt.Sprintf("quickstart.sh has %d %q lines, want 2 (the api-key config and subscription_yaml_body): %s", n, gatewayMasterKeyLine, consequence))
	}
	return out
}

func TestGatewayConfigHasNoUserDatabase(t *testing.T) {
	src := readQuickstartSh(t)

	t.Run("each way the evidence can break is caught", func(t *testing.T) {
		withoutOne := strings.Replace(src, gatewayMasterKeyLine, "", 1)
		for name, mutated := range map[string]string{
			"yaml database_url":      src + "\n  database_url: os.environ/DATABASE_URL\n",
			"DATABASE_URL export":    src + "\nDATABASE_URL=postgres://x litellm --config .agentfactory/litellm.yaml\n",
			"a master_key line lost": withoutOne,
			"a third master_key":     src + "\n" + gatewayMasterKeyLine + "\n",
		} {
			v := strings.Join(gatewayConfigNoDBViolations(mutated), "\n")
			if !strings.Contains(v, "GHSA-7hp6-4w63-5g45") || !strings.Contains(v, "GHSA-g5ff-637f-6q2m") {
				t.Errorf("%s: violation missing or does not name both advisories: %q", name, v)
			}
		}
	})

	for _, v := range gatewayConfigNoDBViolations(src) {
		t.Error(v)
	}
}
